package com.flashsale.coupon;import com.flashsale.common.api.ApiResponse;import com.flashsale.common.security.*;import com.flashsale.common.trace.TraceContext;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/coupons") class CouponClaimController {private final CouponClaimService s;private final JwtTokenService t;CouponClaimController(CouponClaimService s,JwtTokenService t){this.s=s;this.t=t;}@PostMapping("/{templateId}/claims")ApiResponse<Long> claim(@RequestHeader("Authorization")String h,@RequestHeader("Idempotency-Key")String k,@PathVariable long templateId){return ApiResponse.success(s.claim(actor(h),templateId,k),TraceContext.getOrCreate());}@GetMapping("/me")ApiResponse<java.util.List<CouponClaimService.UserCouponView>> mine(@RequestHeader("Authorization")String h,@RequestParam(required=false)String status){return ApiResponse.success(s.mine(actor(h),status),TraceContext.getOrCreate());}private Principal actor(String h){try{if(h==null||!h.startsWith("Bearer "))throw new IllegalArgumentException();return t.parse(h.substring(7));}catch(Exception e){throw new IllegalArgumentException("UNAUTHENTICATED");}}}
